from build import build
S={
'caudal gluteal artery':'A terminal branch of the <b>internal iliac artery</b>. It leaves the pelvis over the greater ischiatic notch to the caudal hip and thigh muscles.',
'cranial gluteal artery':'From the <b>caudal gluteal artery</b>. It crosses the cranial part of the greater ischiatic notch, <b>between the middle and deep gluteals</b>.',
'cranial gluteal nerve':'Travels <b>with the cranial gluteal artery</b> between the middle and deep gluteals, which it supplies, plus the <b>tensor fasciae latae</b>.',
'iliolumbar artery':'A branch of the caudal gluteal artery that runs <b>cranially along the ilium</b> to the lumbar muscles.',
'external iliac artery':'Leaves the aorta at about <b>L6–L7</b> and becomes the <b>femoral artery</b> after passing through the vascular lacuna.',
'vascular lacuna':'The opening between the <b>inguinal ligament and the pelvis</b> where the external iliac artery leaves the abdomen.',
'deep femoral artery':'The <b>only branch of the external iliac</b>, given off inside the abdomen near the vascular lacuna.',
'caudal epigastric artery':'Comes off the <b>pudendoepigastric trunk</b> (from the deep femoral) and runs cranially on the dorsal surface of the <b>rectus abdominis</b>.',
'femoral triangle':'The space bounded by the <b>sartorius</b> (cranial), <b>vastus medialis + rectus femoris</b> (lateral) and <b>pectineus + adductor</b> (caudal). It holds the femoral artery, vein and saphenous nerve.',
'medial circumflex femoral artery':'The <b>continuation of the deep femoral artery</b> after it leaves the abdomen, running caudally between the quadriceps and pectineus into the adductor.',
'deep branch (medial circumflex femoral artery)':'One of the 2 branches of the medial circumflex femoral artery; it runs deep toward the hip joint.',
'transverse branch (medial circumflex femoral artery)':'The other branch of the medial circumflex femoral artery; it runs transversely into the adductor.',
'femoral artery':'The <b>continuation of the external iliac</b> after the vascular lacuna. It runs down the femoral triangle (pulse site) and becomes the <b>popliteal artery</b>.',
'superficial circumflex iliac artery':'The <b>first branch of the femoral artery</b>, going cranially to the sartorius and tensor fasciae latae.',
'lateral circumflex femoral artery':'A femoral branch that dives <b>between the rectus femoris and vastus medialis</b> into the quadriceps.',
'proximal caudal femoral artery':'A femoral branch to the <b>caudal (adductor/hamstring) thigh muscles</b>, the first of 3 caudal femorals.',
'saphenous artery':'Leaves the femoral artery in the <b>middle of the thigh</b> and runs down the medial leg; it splits into cranial and caudal branches.',
'saphenous nerve':'A branch of the <b>femoral nerve</b>. It runs with the femoral artery in the femoral triangle, then along the medial leg (skin of the medial limb).',
'medial saphenous vein':'The superficial vein on the <b>medial</b> crus and thigh, draining into the femoral vein. Common blood-draw site in cats.',
'cranial branch (saphenous artery)':'The branch of the saphenous artery running down the <b>dorsal (cranial) paw</b>.',
'caudal branch (saphenous artery)':'The branch of the saphenous artery running down the <b>plantar (caudal) side</b> of the tarsus and paw.',
'lateral saphenous vein':'The superficial vein on the <b>lateral</b> crus, crossing the lateral hock. Classic dog catheter/blood-draw site.',
'cranial branch (lateral saphenous vein)':'The branch of the lateral saphenous vein on the <b>dorsal (cranial) side</b> of the tarsus.',
'caudal branch (lateral saphenous vein)':'The branch of the lateral saphenous vein on the <b>plantar (caudal) side</b> of the tarsus.',
'descending genicular artery':'A small femoral branch running to the <b>medial side of the stifle</b>.',
'middle caudal femoral artery':'The 2nd caudal femoral artery, into the <b>caudal thigh muscles</b> (adductor, semimembranosus).',
'distal caudal femoral artery':'The last femoral branch before the popliteal, to the <b>gastrocnemius and caudal thigh</b>.',
'popliteal artery':'The <b>continuation of the femoral artery</b> behind the stifle, between the heads of the gastrocnemius. It ends as the cranial tibial artery.',
'cranial tibial artery':'The continuation of the popliteal artery. It runs down the <b>cranial crus with the deep fibular nerve</b> and becomes the dorsal pedal artery.',
}
build(26,'Pelvic limb vessels',S)
